class Solution {
public:
    vector<int> anagramMappings(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, int> index;
        for (int i = 0; i < static_cast<int>(nums2.size()); ++i) {
            index[nums2[i]] = i;
        }
        vector<int> answer;
        for (int x : nums1) {
            answer.push_back(index[x]);
        }
        return answer;
    }
};
